//! ONNX protobuf types (generated by `cargo xtask gen-onnx`) and small helpers.

#[allow(clippy::all, clippy::pedantic, reason = "generated by prost-build")]
mod pb {
    // include! keeps rustfmt off the generated file.
    include!("onnx.rs");
}

pub use pb::*;

/// `TensorProto.DataType.FLOAT`.
pub const FLOAT: i32 = 1;

pub fn decode(bytes: &[u8]) -> Result<ModelProto, prost::DecodeError> {
    <ModelProto as prost::Message>::decode(bytes)
}

pub fn encode(model: &ModelProto) -> Vec<u8> {
    prost::Message::encode_to_vec(model)
}

/// Sets `key` in the model's metadata, replacing an existing entry or appending a new one.
pub fn set_metadata(model: &mut ModelProto, key: &str, value: &str) {
    match model
        .metadata_props
        .iter_mut()
        .find(|e| e.key.as_deref() == Some(key))
    {
        Some(entry) => entry.value = Some(value.to_owned()),
        None => model.metadata_props.push(StringStringEntryProto {
            key: Some(key.to_owned()),
            value: Some(value.to_owned()),
        }),
    }
}

/// The model's metadata value for `key`, if present.
pub fn metadata<'a>(model: &'a ModelProto, key: &str) -> Option<&'a str> {
    model
        .metadata_props
        .iter()
        .find(|e| e.key.as_deref() == Some(key))
        .and_then(|e| e.value.as_deref())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model() -> ModelProto {
        ModelProto {
            ir_version: Some(8),
            graph: Some(GraphProto {
                initializer: vec![TensorProto {
                    name: Some("w".into()),
                    dims: vec![2],
                    data_type: Some(FLOAT),
                    raw_data: Some(vec![0, 0, 128, 63, 0, 0, 0, 64]),
                    ..Default::default()
                }],
                ..Default::default()
            }),
            ..Default::default()
        }
    }

    #[test]
    fn encode_decode_round_trip() {
        let m = model();
        assert_eq!(decode(&encode(&m)).unwrap(), m);
    }

    #[test]
    fn metadata_written_and_read_back() {
        let mut m = model();
        set_metadata(&mut m, "sr", "40000");
        set_metadata(&mut m, "converter", "vc-convert 0.1.0");
        let back = decode(&encode(&m)).unwrap();
        assert_eq!(metadata(&back, "sr"), Some("40000"));
        assert_eq!(metadata(&back, "converter"), Some("vc-convert 0.1.0"));
        assert_eq!(metadata(&back, "missing"), None);
    }

    #[test]
    fn set_metadata_replaces_existing_key() {
        let mut m = model();
        set_metadata(&mut m, "sr", "32000");
        set_metadata(&mut m, "sr", "48000");
        assert_eq!(m.metadata_props.len(), 1);
        assert_eq!(metadata(&m, "sr"), Some("48000"));
    }

    #[test]
    fn decode_garbage_errors() {
        assert!(decode(b"\xff\xff").is_err());
    }
}
